        if (!home) home = "/tmp";
        if (asprintf(&status_script_path, "%s/.entr/status.awk", home) < 0) {
            status_script_path = NULL;
        }
    }

    if (!status_script_path) exit(1);

    if (access(status_script_path, F_OK) != 0) {
        char *dir = strdup(status_script_path);
        char *dname = dirname(dir);
        mkdir(dname, 0700);
        free(dir);

        FILE *f = fopen(status_script_path, "w");
        if (!f) {
            fprintf(stderr, "%s: open: %s\n", progname, strerror(errno));
            exit(1);
        }
        fprintf(f, "# http://eradman.com/entrproject/status-filters.html\n");
        fprintf(f, "/^signal/ { print $3, \"terminated by signal\", $2; }\n");
        fprintf(f, "/^exit/ { print $3, \"returned exit code\", $2; }\n");
        fclose(f);
        printf("entr: created '%s'\n", status_script_path);
        fflush(stdout);
    }
}

static void start_awk_process(void) {
    int pfd[2];
    if (pipe(pfd) < 0) return;

    pid_t pid = fork();
    if (pid < 0) {
        close(pfd[0]);
        close(pfd[1]);
        return;
    }
    if (pid == 0) {
        close(pfd[1]);
        dup2(pfd[0], STDIN_FILENO);
        close(pfd[0]);

        char *awk_args[10];
        int idx = 0;
        awk_args[idx++] = "awk";
        if (opt_x == 1) {
            awk_args[idx++] = "-S";
        }
        awk_args[idx++] = "-F";
        awk_args[idx++] = "|";
        awk_args[idx++] = "-f";
        awk_args[idx++] = status_script_path;
        awk_args[idx] = NULL;

        execvp("awk", awk_args);
        _exit(1);
    }
    close(pfd[0]);
    awk_pipe_fd = pfd[1];
}

static void report_status(const char *type, int val, const char *util) {
    if (awk_pipe_fd >= 0) {
        dprintf(awk_pipe_fd, "%s|%d|%s\n", type, val, util);
    }
}

static int run_utility(char **utility_argv, int utility_argc, const char *trigger_file) {
    if (opt_c == 1) {
        printf("\x1b[2J\x1b[H");
        fflush(stdout);
    } else if (opt_c >= 2) {
        printf("\x1b[2J\x1b[3J\x1b[H");
        fflush(stdout);
    }

    if (opt_r && child_pid > 0) {
        kill(-child_pid, restart_sig);
        int status;
        waitpid(child_pid, &status, 0);
        child_pid = -1;
    }

    char **exec_argv = NULL;
    if (opt_s) {
        exec_argv = malloc(5 * sizeof(char *));
        exec_argv[0] = shell_path;
        exec_argv[1] = "-c";
        exec_argv[2] = utility_argv[0];
        exec_argv[3] = (char *)trigger_file;
        exec_argv[4] = NULL;
    } else {
        exec_argv = malloc((utility_argc + 1) * sizeof(char *));
        bool replaced = false;
        for (int i = 0; i < utility_argc; i++) {
            if (!replaced && strcmp(utility_argv[i], "/_") == 0) {
                exec_argv[i] = (char *)trigger_file;
                replaced = true;
            } else {
                exec_argv[i] = utility_argv[i];
            }
        }
        exec_argv[utility_argc] = NULL;
    }

    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        free(exec_argv);
        return 1;
    }

    if (pid == 0) {
        if (opt_r) {
            setpgid(0, 0);
        }
        if (tty_fd >= 0) {
            restore_terminal();
        }
        execvp(exec_argv[0], exec_argv);
        perror(exec_argv[0]);
        _exit(127);
    }

    child_pid = pid;
    free(exec_argv);

    if (!opt_r) {
        int wstatus;
        waitpid(pid, &wstatus, 0);
        child_pid = -1;

        int exit_status = 0;
        const char *util_name = utility_argv[0];

        if (WIFEXITED(wstatus)) {
            exit_status = WEXITSTATUS(wstatus);
            if (opt_x > 0) report_status("exit", exit_status, util_name);
        } else if (WIFSIGNALED(wstatus)) {
            int sig = WTERMSIG(wstatus);
            exit_status = 128 + sig;
            if (opt_x > 0) report_status("signal", sig, util_name);
        }

        return exit_status;
    }

    return 0;
}

int main(int argc, char **argv) {
    if (argc > 0 && argv[0] && strlen(argv[0]) > 0) {
        char *b = basename(argv[0]);
        if (b) progname = b;
    }

    if (argc < 2) {
        usage(true);
        return 1;
    }

    if (strcmp(argv[1], "-h") == 0) {
        print_summary();
        usage(false);
        return 1;
    }

    int opt;
    opterr = 1;
    while ((opt = getopt(argc, argv, "acdnprsxz")) != -1) {
        switch (opt) {
            case 'a': opt_a = 1; break;
            case 'c': opt_c++; break;
            case 'd': opt_d++; break;
            case 'n': opt_n = 1; break;
            case 'p': opt_p = 1; break;
            case 'r': opt_r = 1; break;
            case 's': opt_s = 1; break;
            case 'x': opt_x++; break;
            case 'z': opt_z = 1; break;
            case '?':
            default:
                usage(true);
                return 1;
        }
    }

    if (optind >= argc) {
        usage(true);
        return 1;
    }

    char **utility_argv = &argv[optind];
    int utility_argc = argc - optind;

    if (opt_s && utility_argc > 1) {
        fprintf(stderr, "%s: -s requires commands to be formatted as a single argument\n", progname);
        return 1;
    }

    if (getenv("ENTR_FOLLOW_SYMLINK")) follow_symlink = true;
    if (getenv("EV_TRACE")) ev_trace = true;
    if (getenv("SHELL")) shell_path = getenv("SHELL");
    if (!getenv("PAGER")) setenv("PAGER", "/bin/cat", 0);

    if (getenv("ENTR_RESTART_SIGNAL")) {
        restart_sig = parse_restart_signal(getenv("ENTR_RESTART_SIGNAL"));
    }

    if (opt_x > 0) {
        setup_status_script();
        start_awk_process();
    }

    // Read filenames from stdin
    char *line = NULL;
    size_t len = 0;
    ssize_t read_bytes;

    while ((read_bytes = getline(&line, &len, stdin)) != -1) {
        while (read_bytes > 0 && (line[read_bytes - 1] == '\n' || line[read_bytes - 1] == '\r')) {
            line[--read_bytes] = '\0';
        }
        if (read_bytes == 0) continue;

        struct stat st;
        int res = follow_symlink ? stat(line, &st) : lstat(line, &st);
        if (res < 0) {
            fprintf(stderr, "%s: unable to stat '%s'\n", progname, line);
            continue;
        }

        list_add(&watched_files, line, -1, &st, S_ISDIR(st.st_mode));

        if (opt_d > 0 || S_ISDIR(st.st_mode)) {
            char *dir_path = NULL;
            if (S_ISDIR(st.st_mode)) {
                dir_path = strdup(line);
            } else {
                char *tmp = strdup(line);
                dir_path = strdup(dirname(tmp));
                free(tmp);
            }
            if (!list_contains(&tracked_dirs, dir_path)) {
                list_add(&tracked_dirs, dir_path, -1, NULL, true);
            } else {
                free(dir_path);
            }
        }
    }
    free(line);

    if (watched_files.count == 0 && tracked_dirs.count == 0) {
        fprintf(stderr, "%s: No regular files to watch\n", progname);
        return 1;
    }

    if (ev_trace) {
        fprintf(stderr, "open_max: %ld\n", sysconf(_SC_OPEN_MAX));
    }

    // Interactive terminal setup
    if (!opt_n) {
        tty_fd = open("/dev/tty", O_RDWR | O_NOCTTY);
        if (tty_fd < 0 || tcgetattr(tty_fd, &orig_termios) < 0) {
            fprintf(stderr, "%s: unable to get terminal attributes, use '-n' to run non-interactively\n", progname);
            return 1;
        }
        struct termios raw = orig_termios;
        cfmakeraw(&raw);
        tcsetattr(tty_fd, TCSANOW, &raw);
        tty_raw_set = true;
        signal(SIGINT, sigint_handler);
    } else {
        signal(SIGINT, sigint_handler);
    }

    int inotify_fd = inotify_init1(IN_CLOEXEC);
    if (inotify_fd < 0) {
        perror("inotify_init1");
        cleanup_and_exit(1);
    }

    for (size_t i = 0; i < watched_files.count; i++) {
        uint32_t mask = IN_CLOSE_WRITE | IN_DELETE_SELF | IN_MOVE_SELF | IN_ATTRIB | IN_MODIFY;
        if (!follow_symlink) mask |= IN_DONT_FOLLOW;
        int wd = inotify_add_watch(inotify_fd, watched_files.items[i].path, mask);
        watched_files.items[i].wd = wd;

        if (ev_trace) {
            fprintf(stderr, "%zu/%zu: fflags: 0x2 r %o %s\n", i, watched_files.count, (unsigned int)(watched_files.items[i].st.st_mode & 07777), watched_files.items[i].path);
        }
    }

    for (size_t i = 0; i < tracked_dirs.count; i++) {
        uint32_t mask = IN_CREATE | IN_DELETE | IN_MOVED_FROM | IN_MOVED_TO;
        int wd = inotify_add_watch(inotify_fd, tracked_dirs.items[i].path, mask);
        tracked_dirs.items[i].wd = wd;
    }

    const char *first_file = watched_files.count > 0 ? watched_files.items[0].path : "";
    int last_exit_status = 0;

    if (!opt_p) {
        last_exit_status = run_utility(utility_argv, utility_argc, first_file);
        if (opt_z && !opt_r) {
            cleanup_and_exit(last_exit_status);
        }
    }

    struct pollfd fds[2];
    int nfds = 0;

    fds[0].fd = inotify_fd;
    fds[0].events = POLLIN;
    nfds = 1;

    if (tty_fd >= 0) {
        fds[1].fd = tty_fd;
        fds[1].events = POLLIN;
        nfds = 2;
    }

    char buf[4096] __attribute__ ((aligned(__alignof__(struct inotify_event))));

    while (1) {
        if (opt_r && child_pid > 0) {
            int status;
            pid_t r = waitpid(child_pid, &status, WNOHANG);
            if (r > 0) {
                child_pid = -1;
                if (opt_z) {
                    int code = 0;
                    if (WIFEXITED(status)) code = WEXITSTATUS(status);
                    else if (WIFSIGNALED(status)) code = 128 + WTERMSIG(status);
                    cleanup_and_exit(code);
                }
            }
        }

        int poll_res = poll(fds, nfds, 100);
        if (poll_res < 0) {
            if (errno == EINTR) continue;
            break;
        }

        if (poll_res == 0) continue;

        bool trigger_run = false;
        const char *trigger_file = first_file;

        if (tty_fd >= 0 && (fds[1].revents & POLLIN)) {
            char c;
            if (read(tty_fd, &c, 1) == 1) {
                if (c == ' ') {
                    trigger_run = true;
                } else if (c == 'q') {
                    cleanup_and_exit(0);
                }
            }
        }

        if (fds[0].revents & POLLIN) {
            ssize_t len = read(inotify_fd, buf, sizeof(buf));
            if (len > 0) {
                const struct inotify_event *event;
                for (char *ptr = buf; ptr < buf + len; ptr += sizeof(struct inotify_event) + event->len) {
                    event = (const struct inotify_event *) ptr;

                    // Check if directory event
                    for (size_t i = 0; i < tracked_dirs.count; i++) {
                        if (tracked_dirs.items[i].wd == event->wd) {
                            if (event->len > 0) {
                                if (event->name[0] == '.' && opt_d < 2) {
                                    // ignore dotfiles unless -dd
                                    continue;
                                }
                                fprintf(stderr, "%s: directory altered\n", progname);
                                cleanup_and_exit(2);
                            }
                        }
                    }

                    // Check if file event
                    for (size_t i = 0; i < watched_files.count; i++) {
                        if (watched_files.items[i].wd == event->wd) {
                            struct stat st;
                            int r = follow_symlink ? stat(watched_files.items[i].path, &st) : lstat(watched_files.items[i].path, &st);
                            if (r < 0) {
                                fprintf(stderr, "%s: cannot open '%s': %s\n", progname, watched_files.items[i].path, strerror(errno));
                                cleanup_and_exit(1);
                            }
                            trigger_run = true;
                            trigger_file = watched_files.items[i].path;
                        }
                    }
                }
            }
        }

        if (trigger_run) {
            if (!opt_a) {
                // Coalesce events: drain inotify_fd
                while (poll(fds, 1, 0) > 0 && (fds[0].revents & POLLIN)) {
                    ssize_t dummy = read(inotify_fd, buf, sizeof(buf));
                    (void)dummy;
                }
            }

            last_exit_status = run_utility(utility_argv, utility_argc, trigger_file);

            if (opt_z && !opt_r) {
                cleanup_and_exit(last_exit_status);
            }
        }
    }

    cleanup_and_exit(last_exit_status);
    return 0;
}
